You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\section{Preliminary}
\label{sec:pre}
\paragraph{Notation} Let $[n] = \{1,2,\ldots, n\}$ and $[n_1: n_2] = \{n_1, n_1+1, \ldots, n_2\}$. Let $\Delta_n$ be all probability distributions over $[n]$.
We use $\langle p, r\rangle$ to denote the inner product of two vectors $p, r$. For any $\mu \in [0,1]$, let $B_\mu$ be the  Bernoulli distribution with mean $\mu$.

\subsection{Online learning}
We consider the standard adversarial online learning setting. 
Let $T$ be the total number of days, $n$ be the number of experts and $B > 0$ be the width of reward sequence.
There is a sequence of $T$ days and at each day $t \in [T]$, the algorithm plays a distribution $p_t \in \Delta_n$ over the set of action $[n]$. After that, the adversary selects a reward vector $r_t \in [0,B]^{n}$. The algorithm observes $r_t$ and receives reward $\langle p_t, r_t\rangle$.
Let $\Phi_n$ be all swap functions that map from $[n]$ to $[n]$, the {\em swap regret} measures the maximum gain one could have obtained when using a fixed swap function over its history strategies
\begin{align*}
\texttt{swap-regret}:=\max_{\phi \in \Phi_n}\sum_{t\in [T]} \sum_{i\in [n]}p_t(i)r_t(\phi(i)) - \sum_{t\in [T]} \langle p_t, r_t\rangle.
\end{align*}

\section{Lower bound}
\label{sec:lower}

\subsection{Hard sequence} 
\label{sec:hard-seq}

Let $K, L$ and $\Delta \in (0,1/20]$ be the input parameters.

\paragraph{$K$-ary Tree} The hard sequence goes over all actions $[n]$ via a depth-first search over a $K$-ary tree. 
The tree has $L+1$ levels and each internal node has $K$ child nodes. 
The root is at level $L$ and the leaves are at level $0$. 
Let $\mT_\ell = [0:K-1]^{L-\ell}$ be all nodes at level $\ell \in [0:L]$ and $\mT = \cup_{\ell \in [0:L]}\mT_\ell$ be all nodes in the tree.
We write $a = a_L\ldots a_{\ell+1} \in \mT_{\ell}$ to denote the $a$-th node at level $\ell$, where $a_{\ell+1}, \ldots, a_{L} \in [0:K-1]$.
We write $a.k$ to denote the $k$-th ($k\in [0:K-1]$) child node of $a$.



There are $K^{L}$ leaf nodes in total and each leaf node $a \in \mT_{0}$ maps to two actions $2a + 1, 2a+2$. 
Here we slightly abuse notation and also view $a$ as a natural number in base $K$.
The action set $\N_a$ of an internal node $a \in \mT_{\ell}$ is the union of its descendants' actions. It has size $n_{\ell} = 2K^{\ell}$ and satisfies 
\[
\N_a := \left[\sum_{\ell'= L}^{\ell+1}a_{\ell'} n_{\ell'-1} + 1: \sum_{\ell'= L}^{\ell'+1}a_{\ell'} n_{\ell'-1} + n_\ell\right].
\]
Let $n = 2K^{L}$ be the total number of actions, the root node includes the entire action set $[n] = [2K^{L}]$.



\paragraph{Reward sequence} The reward sequence is formally depicted in Algorithm \ref{algo:hard-sequence-oblivious}.
Nature visits all leaf nodes in order, but randomly skips some of them.
The visit is constructed recursively. Nature starts from the root node, and at each internal node $a \in \mT_{\ell}$ ($\ell \in [L]$) it visits, Nature goes through the $K$ child nodes in order. 
After completing the visit of each child node, Nature has some chance (w.p. $q =\frac{1}{2K}$) to skip the rest of $a$'s sub-tree (Line \ref{line:skip}).
When Nature visits a leaf node $a \in \mL_0$, it constructs the reward sequence for the next $H = \frac{1}{400\Delta^2}$ days as follow.
For nodes that have already been passed, the reward is set to $-1$, i.e., $r_{i} = -1$ for $i \in [2a]$ (Line \ref{line:reward-played1} and Line \ref{line:reward-played2}). For actions $2a+1, 2a+2$, one draws reward from $\frac{L}{16(L+1)} + \frac{1}{16(L+1)} B_{1/2 + \Delta}$ and the other draws reward from $\frac{L}{16(L+1)} + \frac{1}{16(L+1)} B_{1/2}$.
For the rest of action $i \in [2a+3: n]$, consider the path from root to leaf $a$, and suppose $i \in \N_{a'}$ for node $a' \in \mT_\ell$ in the path (if there are multiple such nodes, take the lowest one), then the reward is set to $\frac{L-\ell}{16(L+1)}$ (Line \ref{line:reward-level}).







\begin{algorithm}[!htbp]
\caption{$\textsc{HardSeq}(\ell, a)$ \Comment{Level $\ell \in [0:L]$, node $a \in \mT_\ell$}}
\label{algo:hard-sequence-oblivious}
\begin{algorithmic}[1]
\If{$\ell= 0$} \Comment{Leaf node}
\State Sample $i^{*}(a)\sim \{1,2\}$ \State Update reward of action $2a+1, 2a+2$
\begin{align*}
r_{2a + i^{*}(a)} \leftarrow &~ \frac{L}{16(L+1)} + \frac{1}{16(L+1)} B_{1/2 + \Delta} \\
r_{2a + 3 - i^{*}(a)} \leftarrow &~ \frac{L}{16(L+1)} + \frac{1}{16(L+1)} B_{1/2} 
\end{align*}
\State Play for $H = \frac{1}{400\Delta^2}$ days \label{line:two-coin2}
\State Update reward $r_{2a+1}\leftarrow -1,  r_{2a+2} \leftarrow -1$ \label{line:reward-played1}
\Else \Comment{Internal node}
\State Update reward $r_i \leftarrow \frac{L-\ell}{16(L+1)}$ for all actions $i \in \N_a$  \label{line:reward-level}
\For{$k = 0,1,\ldots, K-1$} 
\State $\textsc{HardSeq}(\ell-1, a.k)$ \Comment{Visit the $k$-th child node}
\State {\bf with probability} $q = \frac{1}{2K}$ {\bf do} \Comment{Skip rest of the sub-tree}  \label{line:skip}
\State \indent Update reward $r_{i} \leftarrow -1$ for all action $i\in \N_a$ \label{line:reward-played2}
\State \indent {\bf break} 
\EndFor
\EndIf
\end{algorithmic}
\end{algorithm}

\subsection{Analysis}
\label{sec:lower-analysis}

Let $T_{\ALG}$ be the total number of days of Algorithm \ref{algo:hard-sequence-oblivious}.
\begin{lemma}
\label{lem:lower-goal}
Suppose the reward sequence is constructed as in Algorithm \ref{algo:hard-sequence-oblivious}, then any algorithm has expected swap regret at least
\begin{align}
\label{eq:lower-goal}
\E[\texttt{swap-regret}] \geq \min \left\{ \frac{\E[T_{\ALG}]}{KL}, \frac{\E[T_{\ALG}]\Delta}{L} \right\}.
\end{align}
\end{lemma}

The sequence length $T_{\ALG}$ is a random variable, and its expectation satisfies
\begin{lemma}
\label{lem:basic-expecation}
Let $C_{K} = \sum_{k=0}^{K-1}(1-\frac{1}{2K})^{k}$.
We have
\[
\E[T_{\ALG}] = H \cdot (C_K)^{L}  \geq 2^{-L} \cdot \frac{K^{L}}{400\Delta^{2}}.
\]
\end{lemma}


